{
  "name": "@vymalo/opencode-auth-core",
  "version": "0.20.2",
  "description": "Shared OAuth2/OIDC auth core (token flows, cache, logging, security primitives) for the @vymalo OpenCode plugin suite.",
  "license": "MIT",
  "author": "vymalo contributors",
  "homepage": "https://github.com/ADORSYS-GIS/lightbridge-opencode-toolbeit#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ADORSYS-GIS/lightbridge-opencode-toolbeit.git",
    "directory": "packages/opencode-auth-core"
  },
  "bugs": {
    "url": "https://github.com/ADORSYS-GIS/lightbridge-opencode-toolbeit/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "oauth2",
    "oidc",
    "auth",
    "token"
  ],
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./lib": {
      "types": "./dist/lib.d.ts",
      "import": "./dist/lib.js"
    },
    "./package.json": "./package.json"
  },
  "sideEffects": false,
  "files": [
    "dist"
  ],
  "engines": {
    "node": ">=22"
  },
  "publishConfig": {
    "access": "public"
  },
  "devDependencies": {
    "vite": "^8.3.0",
    "vitest": "^5.0.1"
  },
  "scripts": {
    "build": "node ../../scripts/build-package.mjs",
    "lint": "biome lint .",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "vitest run",
    "coverage": "vitest run --coverage",
    "format": "biome format --write .",
    "format:check": "biome format ."
  }
}
